import{_ as d,V as t,W as l,Z as o,$ as a,a0 as i,a1 as e,Y as n,F as r}from"./framework-b1bd8911.js";const p={},s=n("<p>photo-plugin 是 QuickMedia 系列中负责图片风格化处理的工具包，<strong>纯 Java 实现</strong>（基于 BufferedImage 逐像素运算，辅以 jhlabs 图像处理库），不依赖任何外部环境，引入依赖即可使用。</p><p>它的定位是&quot;图片风格化&quot;：不是像 imagic-plugin 那样做旋转、裁剪这类几何编辑，而是给图片&quot;换一种画风&quot;——比如把一张照片变成手绘素描，或者把照片变成一张线稿。这类操作的实现原理多是图像处理中经典的滤波、卷积和混合算法，photo-plugin 把它们封装成了统一的算子（Operator）模型：每个算子对外暴露相同的用法（<code>of</code> 指定算子 → <code>setImg</code> 传图 → 链式配置参数 → <code>asImg</code>/<code>asFile</code> 输出），上手成本很低。</p><p>当前已支持的能力清单（以 <code>operator</code> 目录下实际实现的算子为准）：</p><ol><li><p>素描化：<code>OperatorEnum.SKETCH</code></p><ul><li>灰度化 → 反色 → 高斯模糊 → ColorDodge（颜色减淡）混合，输出手绘素描风格</li><li>支持调节高斯模糊半径 <code>radius</code> 与混合强度 <code>alpha</code></li></ul></li><li><p>边缘检测/线稿提取：<code>OperatorEnum.EDGE</code></p><ul><li>内置六种边缘检测算法，通过 <code>EdgeType</code> 切换： <ul><li><code>SOBEL</code>（默认）、<code>PREWITT</code>、<code>KIRSCH</code>、<code>LAPLACIAN</code>、<code>ROBERTS</code>：基于卷积核的经典梯度算子</li><li><code>CANNY</code>：完整的 Canny 边缘检测流程（高斯平滑 → 梯度 → 非极大值抑制 → 双阈值滞后连接），线条效果最细腻</li></ul></li><li>线条颜色、背景颜色、判定阈值均可自定义，可以输出白底黑线、黑底白线等各种风格的线稿</li></ul></li></ol><p>输出支持 <code>BufferedImage</code>（<code>asImg</code>）和保存文件（<code>asFile</code>）两种方式。</p><p><strong>系列文章</strong></p>",6),u=o("code",null,"PhotoOperateWrapper",-1);function E(_,m){const c=r("RouterLink");return t(),l("div",null,[s,o("ul",null,[o("li",null,[a(c,{to:"/git/quick-media/photo/01.%E5%9B%BE%E7%89%87%E9%A3%8E%E6%A0%BC%E5%8C%96%E5%A4%84%E7%90%86.html"},{default:i(()=>[e("1.图片风格化处理")]),_:1}),e("："),u,e(" 用法总览、素描/边缘检测各算子逐一示例与效果说明、Canny 边缘检测原理简述")])])])}const f=d(p,[["render",E],["__file","index.html.vue"]]);export{f as default};
